### 2.5 취소와 협력적 취소

코루틴의 취소는 **협력적(cooperative)**이다. 코루틴에 취소를 요청한다고 즉시 중단되는 것이 아니라, 코루틴 코드가 취소를 확인하는 지점에서만 실제로 취소된다.

#### 취소 확인 메커니즘

모든 `kotlinx.coroutines`의 suspend 함수(`delay`, `yield`, `withContext` 등)는 내부적으로 취소를 확인한다. 하지만 CPU 집약적 루프처럼 suspend 함수를 호출하지 않는 코드는 명시적으로 취소를 확인해야 한다.

```kotlin
// 취소에 협력하지 않는 나쁜 코드
suspend fun processLargeData(data: List<Item>) {
    for (item in data) {
        heavyComputation(item)  // suspend 함수가 아님
        // 취소 요청이 와도 루프가 끝날 때까지 멈추지 않음!
    }
}

// 취소에 협력하는 좋은 코드
suspend fun processLargeData(data: List<Item>) {
    for (item in data) {
        ensureActive()  // 취소되었으면 CancellationException 발생
        heavyComputation(item)
    }
}
```

#### 취소 확인 방법 세 가지

| 방법 | 동작 | 사용 상황 |
|------|------|----------|
| `isActive` | Boolean 확인 (예외 없음) | 정리 작업이 필요할 때 |
| `ensureActive()` | 취소 시 `CancellationException` 발생 | 즉시 중단이 필요할 때 |
| `yield()` | 취소 확인 + 다른 코루틴에 실행 양보 | CPU 집약적 루프에서 |

```kotlin
// 실무 패턴: 대용량 파일 처리
suspend fun processLargeFile(file: File) = coroutineScope {
    var processedLines = 0

    file.useLines { lines ->
        lines.forEachIndexed { index, line ->
            // 방법 1: ensureActive() - 가장 간결
            ensureActive()

            processLine(line)
            processedLines++

            // 방법 2: yield() - 1000줄마다 다른 코루틴에 양보
            if (index % 1000 == 0) {
                yield()
                logger.info("진행률: $processedLines 줄 처리 완료")
            }
        }
    }

    logger.info("총 $processedLines 줄 처리 완료")
}

// 실무 패턴: isActive로 정리 작업 수행
suspend fun processWithCleanup() = coroutineScope {
    val tempFiles = mutableListOf<File>()

    try {
        while (isActive) {
            val tempFile = createTempFile()
            tempFiles.add(tempFile)
            processFile(tempFile)
        }
    } finally {
        // 취소되더라도 임시 파일 정리는 반드시 수행
        tempFiles.forEach { it.delete() }
        logger.info("임시 파일 ${tempFiles.size}개 정리 완료")
    }
}
```

#### CancellationException의 특별한 처리

`CancellationException`은 코루틴 프레임워크에서 특별하게 취급된다. 이 예외는 "정상적인 취소"로 간주되어 부모에게 전파되지 않는다.

```kotlin
// 주의: CancellationException을 일반 Exception으로 잡지 말 것
suspend fun dangerousCode() {
    try {
        someWork()
    } catch (e: Exception) {  // CancellationException도 잡아버림!
        logger.error("에러", e)
        // 취소가 무시되어 코루틴이 계속 실행됨 - 위험!
    }
}

// 올바른 패턴
suspend fun safeCode() {
    try {
        someWork()
    } catch (e: CancellationException) {
        throw e  // 취소는 다시 던져서 전파시킴
    } catch (e: Exception) {
        logger.error("에러", e)
    }
}

// 더 간결한 방법: runCatching 사용 시 주의
suspend fun alsoSafeCode() {
    // runCatching은 CancellationException도 잡으므로 코루틴에서 주의!
    val result = try {
        someWork()
    } catch (e: CancellationException) {
        throw e
    } catch (e: Exception) {
        handleError(e)
    }
}
```

#### withTimeout과 withTimeoutOrNull

시간 제한이 있는 작업에 활용한다.

```kotlin
// withTimeout - 시간 초과 시 TimeoutCancellationException 발생
suspend fun fetchWithTimeout(): ApiResponse {
    return withTimeout(3000L) {  // 3초 제한
        httpClient.get("/api/data")
    }
    // 3초 초과 시 TimeoutCancellationException (CancellationException 하위 클래스)
}

// withTimeoutOrNull - 시간 초과 시 null 반환 (예외 없음)
suspend fun fetchWithFallback(): ApiResponse {
    return withTimeoutOrNull(3000L) {
        httpClient.get("/api/data")
    } ?: run {
        logger.warn("API 호출 타임아웃, 캐시된 데이터 사용")
        getCachedData()
    }
}

// 실무 패턴: 외부 API 호출에 타임아웃 적용
suspend fun callExternalApi(request: ApiRequest): ApiResponse {
    return withTimeoutOrNull(5000L) {
        retryWithBackoff(maxRetries = 3) {
            httpClient.post("/external/api", request)
        }
    } ?: throw ExternalApiTimeoutException("외부 API 5초 초과")
}
```

