### 2.8 Spring WebFlux + 코루틴 통합

Spring WebFlux는 Kotlin 코루틴을 1급 시민으로 지원한다. `suspend` 함수와 `Flow`를 컨트롤러에서 직접 사용할 수 있다.

#### 기본 통합

```kotlin
@RestController
@RequestMapping("/api/orders")
class OrderController(
    private val orderService: OrderService
) {
    // suspend 함수: 단일 응답
    @GetMapping("/{id}")
    suspend fun getOrder(@PathVariable id: Long): ResponseEntity<OrderDto> {
        val order = orderService.findById(id)
        return ResponseEntity.ok(order.toDto())
    }

    // suspend 함수: POST 요청
    @PostMapping
    suspend fun createOrder(@RequestBody request: CreateOrderRequest): ResponseEntity<OrderDto> {
        val order = orderService.create(request)
        return ResponseEntity
            .created(URI("/api/orders/${order.id}"))
            .body(order.toDto())
    }

    // Flow: Server-Sent Events 스트리밍
    @GetMapping("/stream", produces = [MediaType.TEXT_EVENT_STREAM_VALUE])
    fun streamOrders(): Flow<OrderDto> {
        return orderService.streamAll()
            .map { it.toDto() }
    }

    // Flow: 대량 데이터 스트리밍 (메모리 효율적)
    @GetMapping("/export")
    fun exportOrders(
        @RequestParam from: LocalDate,
        @RequestParam to: LocalDate
    ): Flow<OrderDto> {
        return orderService.findByDateRange(from, to)
            .map { it.toDto() }
        // 수만 건의 데이터도 메모리에 전부 올리지 않고 스트리밍
    }
}
```

#### Service 계층에서의 코루틴 활용

```kotlin
@Service
class OrderService(
    private val orderRepository: OrderRepository,
    private val paymentClient: PaymentClient,
    private val inventoryClient: InventoryClient,
    private val notificationService: NotificationService
) {
    // 단일 조회
    suspend fun findById(id: Long): Order {
        return withContext(Dispatchers.IO) {
            orderRepository.findById(id)
                ?: throw OrderNotFoundException("주문을 찾을 수 없습니다: $id")
        }
    }

    // 병렬 처리: 독립적인 외부 호출을 동시에 실행
    suspend fun getOrderDetail(id: Long): OrderDetailDto = coroutineScope {
        val order = async { findById(id) }
        val paymentInfo = async { paymentClient.getPaymentInfo(id) }
        val deliveryInfo = async { inventoryClient.getDeliveryStatus(id) }

        OrderDetailDto(
            order = order.await(),
            payment = paymentInfo.await(),
            delivery = deliveryInfo.await()
        )
        // 3개의 호출이 병렬로 실행 → 총 소요 시간 = max(각 호출 시간)
    }

    // Flow: 데이터 스트리밍
    fun streamAll(): Flow<Order> {
        return orderRepository.findAllAsFlow()
            .onEach { order ->
                logger.debug("스트리밍: ${order.id}")
            }
    }
}
```

