### 2.9 코루틴 테스트

코루틴 테스트는 `kotlinx-coroutines-test` 라이브러리가 제공하는 `runTest`를 사용한다. 핵심은 **가상 시간(virtual time)**을 제어하여, `delay`가 포함된 코드도 즉시 테스트할 수 있다는 점이다.

```kotlin
// build.gradle.kts
// testImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.7.x")

class OrderServiceTest {

    private val mockPaymentClient = mockk<PaymentClient>()
    private val mockNotificationService = mockk<NotificationService>()
    private val mockRepository = mockk<OrderRepository>()

    @Test
    fun `주문 생성 시 결제와 알림이 병렬로 처리된다`() = runTest {
        // Given
        val testOrder = Order(id = 1L, amount = 10000)
        coEvery { mockPaymentClient.process(any()) } returns PaymentResult.Success
        coEvery { mockNotificationService.send(any()) } returns Unit
        coEvery { mockRepository.save(any()) } returns testOrder

        val service = OrderService(
            paymentClient = mockPaymentClient,
            notificationService = mockNotificationService,
            repository = mockRepository
        )

        // When
        val result = service.createOrder(testOrder)

        // Then
        advanceUntilIdle()  // 모든 코루틴이 완료될 때까지 가상 시간 진행

        assertEquals(OrderStatus.CONFIRMED, result.status)
        coVerify { mockPaymentClient.process(any()) }
        coVerify { mockNotificationService.send(any()) }
    }

    @Test
    fun `타임아웃 시 적절한 예외가 발생한다`() = runTest {
        // Given
        coEvery { mockPaymentClient.process(any()) } coAnswers {
            delay(10_000)  // 10초 소요 (가상 시간)
            PaymentResult.Success
        }

        val service = OrderService(
            paymentClient = mockPaymentClient,
            notificationService = mockNotificationService,
            repository = mockRepository
        )

        // When & Then
        assertThrows<PaymentTimeoutException> {
            service.processPaymentWithTimeout(
                Order(id = 1L, amount = 10000),
                timeoutMs = 5000  // 5초 타임아웃
            )
        }
        // delay(10_000)이지만 실제 테스트 시간은 밀리초 단위
    }

    @Test
    fun `Flow가 올바른 순서로 데이터를 방출한다`() = runTest {
        // Given
        val orders = listOf(
            Order(1L, "ORDER-001"),
            Order(2L, "ORDER-002"),
            Order(3L, "ORDER-003")
        )
        coEvery { mockRepository.findAllAsFlow() } returns orders.asFlow()

        val service = OrderService(repository = mockRepository)

        // When
        val result = service.streamAll().toList()

        // Then
        assertEquals(3, result.size)
        assertEquals("ORDER-001", result[0].orderNumber)
        assertEquals("ORDER-003", result[2].orderNumber)
    }

    @Test
    fun `취소가 정상적으로 전파된다`() = runTest {
        var wasCleanedUp = false

        val job = launch {
            try {
                delay(Long.MAX_VALUE)  // 무한 대기
            } finally {
                wasCleanedUp = true
            }
        }

        advanceTimeBy(100)
        job.cancel()
        advanceUntilIdle()

        assertTrue(wasCleanedUp)
        assertTrue(job.isCancelled)
    }
}
```

#### TestDispatcher 종류

```kotlin
// StandardTestDispatcher - 명시적으로 시간을 진행시켜야 함
@Test
fun `StandardTestDispatcher 사용`() = runTest {
    var result = ""
    launch { result = "완료" }

    // 여기서 result는 아직 ""
    assertEquals("", result)

    advanceUntilIdle()  // 명시적으로 진행
    assertEquals("완료", result)
}

// UnconfinedTestDispatcher - launch 즉시 실행
@Test
fun `UnconfinedTestDispatcher 사용`() = runTest(UnconfinedTestDispatcher()) {
    var result = ""
    launch { result = "완료" }

    // 즉시 실행되어 result가 이미 "완료"
    assertEquals("완료", result)
}
```

