## 3. 실무 사례

### 사례 1: 주문 처리 시스템에서의 supervisorScope 활용

대규모 이커머스 시스템에서 주문 처리 후 여러 후속 작업(알림, 포인트 적립, 통계 갱신)을 병렬로 수행해야 한다. 핵심 작업(결제)은 반드시 성공해야 하지만, 부가 작업은 실패해도 주문 자체에 영향을 주면 안 된다.

```kotlin
@Service
class OrderProcessingService(
    private val paymentService: PaymentService,
    private val notificationService: NotificationService,
    private val pointService: PointService,
    private val analyticsService: AnalyticsService
) {
    suspend fun completeOrder(order: Order): OrderResult {
        // 1단계: 결제 처리 (필수 - 실패 시 전체 실패)
        val paymentResult = paymentService.charge(order)
        if (!paymentResult.isSuccess) {
            return OrderResult.PaymentFailed(paymentResult.reason)
        }

        // 2단계: 후속 작업 (부분 실패 허용)
        val sideEffects = supervisorScope {
            val notification = async {
                runCatching { notificationService.sendOrderConfirmation(order) }
            }
            val points = async {
                runCatching { pointService.accumulate(order.userId, order.amount) }
            }
            val analytics = async {
                runCatching { analyticsService.trackPurchase(order) }
            }

            SideEffectResults(
                notificationSent = notification.await().isSuccess,
                pointsAccumulated = points.await().getOrDefault(0),
                analyticsTracked = analytics.await().isSuccess
            )
        }

        // 실패한 부가 작업은 재시도 큐에 등록
        if (!sideEffects.notificationSent) {
            retryQueue.enqueue(RetryTask.Notification(order.id))
        }

        return OrderResult.Success(paymentResult, sideEffects)
    }
}
```

### 사례 2: GlobalScope 메모리 누수 장애

실제 장애 시나리오: 배포 후 서버 메모리가 점진적으로 증가하여 4시간 후 OOM(OutOfMemory) 발생.

```kotlin
// 문제 코드: 요청마다 GlobalScope로 코루틴 생성
@Service
class LegacyNotificationService {
    fun sendAsync(userId: Long, message: String) {
        GlobalScope.launch {
            // 외부 푸시 서비스 호출 (평균 2초, 최대 30초)
            pushService.send(userId, message)
        }
        // 이 코루틴은 아무도 관리하지 않음
        // 푸시 서비스가 느려지면 코루틴이 계속 쌓임
        // 서버 재시작 전까지 GC되지 않음
    }
}

// 수정 코드: 관리 가능한 스코프 + 동시성 제한
@Service
class ManagedNotificationService {
    private val notificationDispatcher = Dispatchers.IO.limitedParallelism(20)
    private val scope = CoroutineScope(
        SupervisorJob() + notificationDispatcher + CoroutineName("notification")
    )

    fun sendAsync(userId: Long, message: String) {
        scope.launch {
            withTimeoutOrNull(10_000) {  // 10초 타임아웃
                pushService.send(userId, message)
            } ?: logger.warn("푸시 발송 타임아웃: userId=$userId")
        }
    }

    @PreDestroy
    fun shutdown() {
        scope.cancel()  // 빈 소멸 시 모든 코루틴 정리
    }
}
```

### 사례 3: 외부 API 병렬 호출 패턴

상품 상세 페이지를 구성하기 위해 여러 마이크로서비스에서 데이터를 가져와야 하는 상황. 순차 호출하면 5초, 병렬 호출하면 1.5초로 단축.

```kotlin
@Service
class ProductDetailService(
    private val productClient: ProductClient,
    private val reviewClient: ReviewClient,
    private val recommendClient: RecommendClient,
    private val priceClient: PriceClient
) {
    suspend fun getProductDetail(productId: Long): ProductDetailDto = coroutineScope {
        // 필수 데이터: 하나라도 실패하면 전체 실패
        val product = async { productClient.getProduct(productId) }
        val price = async { priceClient.getPrice(productId) }

        // 선택적 데이터: 실패해도 기본값 사용
        val reviews = async {
            withTimeoutOrNull(2000) {
                reviewClient.getReviews(productId)
            } ?: emptyList()  // 타임아웃이면 리뷰 없이 표시
        }

        val recommendations = async {
            withTimeoutOrNull(1500) {
                recommendClient.getRecommendations(productId)
            } ?: emptyList()  // 추천 없이 표시
        }

        ProductDetailDto(
            product = product.await(),      // 필수
            price = price.await(),          // 필수
            reviews = reviews.await(),      // 선택적
            recommendations = recommendations.await()  // 선택적
        )
    }
}
```

